func activeStart(conv []nacelle.Message, n, anchor, keep int) int {
	want := clamp(n-keep, anchor, n)
	if want <= anchor {
		return want
	}
	cut := max(AlignedCut(conv, want), anchor)
	if cut < want && IsLedger(conv[cut]) {
		return want
	}
	return cut
}
